/**
 * Throws when granting a billable role to a currently-free (`viewer`) member
 * would exceed the plan's seat quota. Seats in use are counted exactly as for
 * invitations: billable active members plus pending billable invitations.
 */
async function assertSeatAvailable(orgId: OrgId): Promise<void> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const seatsUsed =
    (await memberRepo.countActiveBillableMembers(orgId)) +
    (await invitationRepo.countPendingBillableInvitations(orgId));

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, 1)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }
}

